+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.Collection;
+import java.util.Collections;
+import java.util.EnumSet;
+import java.util.List;
+import java.util.Locale;
+import java.util.Set;
+import java.util.function.Predicate;
+import java.util.regex.Pattern;
+
+/** The name and status restrictions for a customer query. */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) {
+
+    private static final Pattern WHITESPACE = Pattern.compile("\\s+", Pattern.UNICODE_CHARACTER_CLASS);
+    private static final Pattern COMBINING_MARKS = Pattern.compile("\\p{M}+");
+
+    public CustomerFilter {
+        name = name == null ? "" : name;
+        if (statuses == null || statuses.isEmpty()) {
+            statuses = Set.of();
+        } else {
+            statuses = Collections.unmodifiableSet(EnumSet.copyOf(statuses));
+        }
+    }
+
+    public static CustomerFilter empty() {
+        return new CustomerFilter("", Set.of());
+    }
+
+    public static CustomerFilter of(String name, Collection<CustomerStatus> statuses) {
+        return new CustomerFilter(name, statuses == null ? Set.of() : Set.copyOf(statuses));
+    }
+
+    /**
+     * Builds the predicate once per backend query, so normalization is not
+     * repeated for each name term and each customer.
+     */
+    public Predicate<Customer> toPredicate() {
+        List<String> terms = WHITESPACE.splitAsStream(name.strip())
+                .filter(term -> !term.isEmpty())
+                .map(CustomerFilter::normalize)
+                .toList();
+
+        return customer -> {
+            if (!statuses.isEmpty() && !statuses.contains(customer.status())) {
+                return false;
+            }
+            String firstName = normalize(customer.firstName());
+            String lastName = normalize(customer.lastName());
+            return terms.stream().allMatch(term -> firstName.contains(term) || lastName.contains(term));
+        };
+    }
+
+    private static String normalize(String value) {
+        String decomposed = Normalizer.normalize(value, Normalizer.Form.NFD);
+        return COMBINING_MARKS.matcher(decomposed).replaceAll("").toLowerCase(Locale.ROOT);
+    }
+}
